const fileName = "MgfrOFR-round2-gptpro-polish.zip";
const mimeType = "application/zip";
const base64 = "";
function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
const inputs = Array.from(document.querySelectorAll('input[type=file]'));
const input = inputs.find((candidate) => !candidate.disabled) || inputs[0];
if (!input) return { ok: false, error: 'no input[type=file] found' };
const file = new File([decodeBase64(base64)], fileName, { type: mimeType });
const dt = new DataTransfer();
dt.items.add(file);
input.files = dt.files;
input.dispatchEvent(new Event('input', { bubbles: true }));
input.dispatchEvent(new Event('change', { bubbles: true }));
return {
  ok: input.files && input.files.length === 1,
  input_count: inputs.length,
  uploaded: Array.from(input.files || []).map((item) => ({
    name: item.name,
    size: item.size,
    type: item.type,
  })),
};
